definition.script:
pipeline {
    agent any
    environment {
        // 定义容器内工作目录
        CONTAINER_WORKSPACE = "/workspace"
    }
    stages {
        stage('拉取训练数据') {
            steps {
                script {
                    // 创建数据集目录
                    sh "mkdir -p /opt/mlops/datasets/${DATASET_PATH}"

                    // 从 HDFS 获取数据
                    sh "hdfs dfs -get /datasets/${DATASET_FOLDER} /opt/mlops/datasets/${DATASET_PATH}"
                }
            }
        }

        stage('构建训练任务') {
            steps {
                git(
                    url: "${GIT_REPO_URL}",
                    credentialsId: "${CREDENTIALS_ID}",
                    branch: "${GIT_BRANCH}",
                    changelog: true,
                    poll: false
                )
            }
        }

        stage('构建训练环境') {
            steps {
                script {
                    // 1. 登录Harbor仓库
                    withCredentials([usernamePassword(
                        credentialsId: "${HARBOR_CREDENTIALS_ID}",
                        usernameVariable: 'HARBOR_USER',
                        passwordVariable: 'HARBOR_PASSWORD'
                    )]) {
                        sh """
                        sudo docker login -u $HARBOR_USER -p $HARBOR_PASSWORD ${HARBOR_URL}
                        """
                    }
                    def cleanHarborUrl = "${HARBOR_URL}".replaceFirst(/^https?:\/\//, '')  // 移除协议头

                    // 构建镜像标签列表
                    def tags = "${DOCKER_IMAGE_TAGS}".split(',').collect { tag ->
                        "${cleanHarborUrl}/xnet-mlops-smp-python/${DOCKER_IMAGE_NAME}:${tag.trim()}"
                    }

                    // 拉取所有标签的镜像
                    tags.each { fullTag ->
                         sh "sudo docker pull ${fullTag}"
                    }
                }  // 修复：添加了缺失的 script 块闭合括号
            }
        }

        stage('模型训练') {
            steps {
                script {
                    def cleanHarborUrl = "${HARBOR_URL}".replaceFirst(/^https?:\/\//, '')
                    def tags = "${DOCKER_IMAGE_TAGS}".split(',').collect { tag ->
                        "${cleanHarborUrl}/xnet-mlops-smp-python/${DOCKER_IMAGE_NAME}:${tag.trim()}"
                    }

                    tags.each { fullTag ->
                        // 在Docker容器内执行训练
                        sh """
                        sudo docker run --rm --name ${CONTAINER_NAME} \
                        -v ${WORKSPACE}:${CONTAINER_WORKSPACE} \
                        -v /opt/mlops/datasets/${DATASET_PATH}:${CONTAINER_WORKSPACE}/data \
                        -v ${MODEL_OUTPUT_PATH}:${CONTAINER_WORKSPACE}/model_output \
                        -w ${CONTAINER_WORKSPACE} \
                        ${fullTag} \
                        python ${PYTHON_ENTRY}
                        """
                    }
                }
            }
        }

        stage('模型输出') {
            steps {
                script {
                    // 确保HDFS目录存在
                    sh "hdfs dfs -mkdir -p /output/${DATASET_FOLDER}/${MODEL_OUTPUT_PATH}/"

                    // 上传模型到HDFS
                    sh """
                    if [ -d "${MODEL_OUTPUT_PATH}" ] && [ -n "\$(ls -A '${MODEL_OUTPUT_PATH}')" ]; then
                        hdfs dfs -put -f ${MODEL_OUTPUT_PATH}/* /output/${DATASET_FOLDER}/${MODEL_OUTPUT_PATH}/
                    else
                       echo "##[警告] 模型输出目录为空或不存在: ${MODEL_OUTPUT_PATH}"
                    fi
                """
                }
            }
        }
    }
    post {
        always {
            script {
                // 清理数据集目录
                echo "正在清理数据集目录..."
                sh "sudo rm -rf /opt/mlops/datasets/${DATASET_PATH}"

                // 清理Docker镜像
                def cleanHarborUrl = "${HARBOR_URL}".replaceFirst(/^https?:\/\//, '')
                def tags = "${DOCKER_IMAGE_TAGS}".split(',').collect { tag ->
                    "${cleanHarborUrl}/xnet-mlops-smp-python/${DOCKER_IMAGE_NAME}:${tag.trim()}"
                }

                tags.each { fullTag ->
                    sh "sudo docker rmi ${fullTag} || true"
                }

                // 退出Harbor登录
                sh "sudo docker logout ${HARBOR_URL} || true"
            }
        }
    }
}
